private PendingBuildStart releaseBuilderAndTakePending() {
  lock.lock();
  try {
    builderInUse = false;
    final var successor = pendingBuilderStart;
    pendingBuilderStart = null;
    return successor == null ? null : new PendingBuildStart(this.connectGeneration, successor);
  } finally {
    lock.unlock();
  }
}
